DECLARE @now datetimeoffset=SYSDATETIMEOFFSET();
DECLARE @seed TABLE(ProductId varchar(100) NOT NULL,Slug varchar(100) NOT NULL,DraftJson nvarchar(max) NOT NULL,PublicJson nvarchar(max) NOT NULL);
INSERT @seed(ProductId,Slug,DraftJson,PublicJson)
SELECT JSON_VALUE(item.value,'$.productId'),JSON_VALUE(item.value,'$.slug'),JSON_QUERY(item.value,'$.draft'),
(
 SELECT JSON_VALUE(item.value,'$.productId') AS id,JSON_VALUE(item.value,'$.slug') AS slug,
        JSON_QUERY(item.value,'$.draft.translations') AS translations,
        JSON_QUERY((SELECT JSON_QUERY(media.value,'$.media') AS media FROM OPENJSON(item.value,'$.draft.media') media FOR JSON PATH)) AS media,
        JSON_QUERY(item.value,'$.draft.measurements') AS measurements,JSON_QUERY(N'[]') AS skus,N'mock' AS mode
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
)
FROM OPENJSON(@showcase) item;
IF (SELECT COUNT(*) FROM @seed)<>15 THROW 51000,'DEMO_CATALOG_SEED_COUNT_INVALID',1;
IF EXISTS(SELECT 1 FROM m0.CatalogProducts p JOIN @seed s ON p.Dataset='demo_m0' AND (p.ProductId=s.ProductId OR p.Slug=s.Slug))
 THROW 51000,'DEMO_CATALOG_SEED_COLLISION',1;
IF EXISTS(SELECT 1 FROM @seed product CROSS APPLY OPENJSON(product.DraftJson,'$.skus') sku
          JOIN m0commerce.Inventory i ON i.Dataset='demo_m0' AND i.Sku=JSON_VALUE(sku.value,'$.id'))
 THROW 51000,'DEMO_CATALOG_SEED_SKU_COLLISION',1;
INSERT m0commerce.Inventory(Dataset,Sku,Price,Stock,Active)
SELECT 'demo_m0',JSON_VALUE(sku.value,'$.id'),TRY_CONVERT(bigint,JSON_VALUE(sku.value,'$.unitPriceTwd')),8,1
FROM @seed product CROSS APPLY OPENJSON(product.DraftJson,'$.skus') sku;
INSERT m0.CatalogProducts(Dataset,ProductId,Slug,PublicSlug,State,Version,PublicRevision,DraftJson,PublicJson,OwnerId,CreatedAt,UpdatedAt)
SELECT 'demo_m0',ProductId,Slug,Slug,'Published',1,'generated-demo-v1',DraftJson,PublicJson,'demo_catalog_seed',@now,@now FROM @seed;
INSERT m0.CatalogProductSkus(Dataset,SkuId,ProductId,ColorId,GarmentSize,DraftPriceTwd,DraftActive,DraftIncluded,PublicPriceTwd,PublicActive,PublicIncluded)
SELECT 'demo_m0',JSON_VALUE(sku.value,'$.id'),product.ProductId,JSON_VALUE(sku.value,'$.colorId'),
       JSON_VALUE(sku.value,'$.garmentSize'),TRY_CONVERT(bigint,JSON_VALUE(sku.value,'$.unitPriceTwd')),1,1,
       TRY_CONVERT(bigint,JSON_VALUE(sku.value,'$.unitPriceTwd')),1,1
FROM @seed product CROSS APPLY OPENJSON(product.DraftJson,'$.skus') sku;
